/// every feature hook slot of this crate and the crates below, with whether it is filled
pub fn feature_hook_slots() -> Vec<(&'static str, bool)> {
    fn state<T>(slot: &'static crate::core::feature_hooks::feature_hooks::FeatureHookSlot<T>) -> (&'static str, bool) {
        (slot.name(), slot.is_installed())
    }
    let mut slots: Vec<(&'static str, bool)> = Vec::new();
    slots.extend(riseonly_data_mid::feature_hook_slots());
    slots.push(state(&crate::modules::bot::stores::bot::bot_services::bot_guide_sandbox_hooks::HOOKS));
    slots.push(state(&crate::modules::diagnostics::stores::diagnostics_guide_sandbox_hooks::HOOKS));
    slots.push(state(&crate::modules::media_picker::editor::media_editor_view_hooks::MEDIA_EDITOR_VIEW_HOOKS));
    slots.push(state(&crate::modules::media_picker::ui::media_picker_camera_hooks::MEDIA_PICKER_CAMERA_HOOKS));
    slots.push(state(&crate::modules::moderation::engine::moderation_domain_hooks::MODERATION_DOMAIN_HOOKS));
    slots.push(state(&crate::modules::notify::stores::notify_services::notify_guide_sandbox_hooks::NOTIFY_GUIDE_SANDBOX_HOOKS));
    slots.push(state(&crate::modules::stickers::stores::stickers::stickers_guide_sandbox_hooks::HOOKS));
    slots.push(state(&crate::modules::story::shared::story_guide_sandbox_hooks::HOOKS));
    slots.push(state(&crate::modules::vacancy::stores::vacancy_guide_sandbox_hooks::HOOKS));
    slots
}
